import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Existing two owner command edges use their original pre-mutation companion stamp. */
public final class SummonGroupMethods {
 static final String P="local/lito381/server/",OWNER=P+"ClientSession",H=P+"NativeSummonOwnerLifecycle";
 static ClassNode read(JarFile j)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(OWNER+".class")).readAllBytes()).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static void patch(ClassNode c){int roots=0;for(var m:c.methods)if(Set.of("hypertextAction","handleClassicWorldCompanionAction").contains(m.name)){int stamp=-1,captures=0,ports=0;for(var i:m.instructions)if(i instanceof MethodInsnNode call&&call.owner.equals(P+"NativeCompanionCallbacks")&&call.name.equals("capture")){var store=next(i);if(!(store instanceof VarInsnNode v)||v.getOpcode()!=ASTORE)throw new AssertionError("original companion stamp local");stamp=v.var;captures++;}if(captures!=1)throw new AssertionError("one original companion stamp per owner handler "+m.name);for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(H)&&call.name.equals("apply")){m.instructions.insertBefore(i,new VarInsnNode(ALOAD,stamp));call.desc=call.desc.replace(")L", "L"+P+"NativeCompanionCallbacks$Stamp;)L");ports++;}if(ports!=1)throw new AssertionError("one original apply edge per handler");roots++;}if(roots!=2)throw new AssertionError("two original owner handlers");}
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[1])){var c=read(old);patch(c);var expected=bytes(c);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(OWNER+".class");Files.createDirectories(p.getParent());Files.write(p,expected);}else try(var candidate=new JarFile(a[2])){if(!Arrays.equals(expected,bytes(read(candidate))))throw new AssertionError("owner edge regeneration differs");}System.out.println("PASS two existing command edges append original stamp; all other PC methods/fields retained");}}
}
